export function findKnowledgeMajor(slug: string | undefined) {
  return knowledgeMajors.find((major) => major.slug === slug);
}

export function findKnowledgeTopic(major: KnowledgeMajor, slug: string | undefined) {
  return major.topics.find((topic) => topic.slug === slug);
}
